function overview(){const c=lastCI(),T=today(),sorted=S.checkins.slice().sort((a,b)=>b.at-a.at),last=nights()[0],st=sleepStats(),se=sleepEnergy(),[a,b]=dayRange(T),acts=clip(a,b).sort((x,y)=>y.s-x.s).slice(0,2),ts=S.tasks.filter(t=>t.date===T),dn=ts.filter(t=>t.done).length;
const m=(k,l,col)=>{const r=sorted.find(x=>x[k]!=null);if(!r)return`<div><small>${l.toUpperCase()}</small><b style="color:var(--mut)">—</b><span class="m">Not rated yet</span><button class="wchp" data-act="wb">Record</button></div>`;const prev=sorted.find(x=>x[k]!=null&&x.at<r.at&&ymd(new Date(x.at))===ymd(new Date(r.at))),df=prev?r[k]-prev[k]:null;return`<div><small>${l.toUpperCase()}</small><b style="color:${col}">${r[k]}</b><span class="m">${ago(r.at)}${df==null?'':df===0?' · same as '+fmtT(prev.at):' · '+Math.abs(df)+(df>0?' higher':' lower')+' than '+fmtT(prev.at)}</span></div>`};
return`<section class="box glass" style="padding:16px 15px"><div class="ttl2"><span>Latest check-in</span><span>${c?fmtT(c.at)+' · '+ago(c.at):''}</span></div><div style="display:flex;gap:16px;align-items:center">${orbHtml(84,c&&c.mood)}<p class="hint" style="margin:0">${c?(Date.now()-c.at>18e5?'Recorded earlier. It may not describe how you feel right now.':'Just recorded.'):'No check-in yet. Your first one takes about 20 seconds.'}</p></div><button class="btn pri full" style="width:100%;margin-top:14px" data-act="wb">Quick check-in</button></section>
<div class="wg2" style="margin-top:12px">${m('energy','Energy','#60a5fa')}${m('focus','Focus','#a3e635')}${m('mood','Mood','#34d399')}${m('motivation','Motivation','#fbbf24')}</div>
<section class="box glass" style="padding:16px 15px"><div class="ttl2"><span>Sleep</span><span>${last?(ymd(new Date(last.end))===T?'Last night':dl(ymd(new Date(last.end)))):''}</span></div>${last?`<div class="big">${fmtM(sDur(last))}</div><div style="color:var(--mut);font-size:13px">${last.approx?'~':''}${fmtT(last.start)} → ${last.approx?'~':''}${fmtT(last.end)}${last.q!=null?' · quality '+last.q+'/10':''}${last.rest!=null?' · rested '+last.rest+'/10':''}</div>${st&&st.n>1?`<p class="hint" style="margin:8px 0 0">Typical bedtime ${tmStr(st.bed)}, based on ${st.n} recorded nights.</p>`:''}`:'<div class="empty">No sleep recorded yet.</div><button class="btn full" style="width:100%" data-act="slnew">Log sleep</button>'}</section>
<section class="box glass" style="padding:16px 15px;margin-top:12px"><div class="ttl2"><span>Activity and tasks today</span><span>From your records</span></div>${acts.length?acts.map(x=>`<div class="wkv"><span>${esc(actOf(x.e.actId).name)}</span><b>${fmtT(x.s)}–${x.e.run?'now':fmtT(x.t)}</b></div>`).join(''):'<p class="hint" style="margin:0 0 6px">No activities logged today.</p>'}<div class="wkv"><span>Tasks planned for today</span><b>${ts.length}</b></div><div class="wkv"><span>Completed</span><b>${dn}</b></div><div class="wkv"><span>Not completed yet</span><b>${ts.length-dn}</b></div></section>
<section class="box glass" style="padding:16px 15px;margin-top:12px"><div class="ttl2"><span>Insight preview</span></div>${se.hi.n&&se.lo.n?`${evp(se.ev)}<p class="ip" style="font-size:15px;line-height:1.5;margin:10px 0 6px">Morning energy averaged ${se.hi.avg.toFixed(1)} after nights of 7 hours or more (n = ${se.hi.n}) and ${se.lo.avg.toFixed(1)} after shorter nights (n = ${se.lo.n}).</p><p class="hint" style="margin:0">An association in your records, not proof of cause.</p>`:'<p class="hint" style="margin:0">Insights appear after a few days of sleep and morning energy records. Nothing is guessed in the meantime.</p>'}</section>`}
function ciView(){return ciList()}
function wbStrip(){return`<div class="wsn">${[['overview','Overview'],['sleep','Sleep'],['checkins','Check-ins'],['timeline','Timeline']].map(([k,l])=>`<button class="${wsec===k?'on':''}" data-act="wsec" data-v="${k}">${l}</button>`).join('')}</div>`}
function wellbeing(){return`<div style="height:22px"></div>`+sech('Wellbeing','Mood, energy, focus, motivation and sleep')+wbStrip()+(wsec==='sleep'?sleepView():wsec==='checkins'?ciView():wsec==='timeline'?tlView():overview())}
function home(){const T=today(),ts=S.tasks.filter(t=>t.date===sel),done=ts.filter(t=>t.done).length,sc=dayScore(sel),days=[...Array(7)].map((_,i)=>addD(ws,i)),has=new Set(S.tasks.map(t=>t.date)),c=lastCI(),mid=pd(days[3]).toLocaleDateString(undefined,{month:'long',year:'numeric'}),off=289*(1-(sc.score||0)/100);
return`${demoBar()}<section class="week glass" style="margin-top:0"><div class="topline"><button class="lk" data-act="wk" data-v="-7" aria-label="Previous days">‹</button><div class="tiny">${mid.toUpperCase()}</div><button class="lk" data-act="wk" data-v="7" aria-label="Next days">›</button></div>
<div class="days" id="wk">${days.map(x=>`<button class="day${x===sel?' sel':''}${x===T?' td':''}" data-act="day" data-v="${x}"><small>${pd(x).toLocaleDateString(undefined,{weekday:'short'}).toUpperCase()}</small><b>${pd(x).getDate()}</b><u class="${has.has(x)?'on':''}"></u></button>`).join('')}</div></section>
${sel!==T?`<div class="tdy"><button data-act="gototoday">${sel>T?'← Back to today':'Back to today →'}</button></div>`:''}
<button class="box glass scc" data-act="scoreinfo" aria-label="Open score breakdown"><div class="ring"><svg viewBox="0 0 112 112" aria-hidden="true"><defs><linearGradient id="rg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#777"/><stop offset="1" stop-color="#f4f4f4"/></linearGradient></defs><circle class="tr" cx="56" cy="56" r="46"/><circle class="pg" cx="56" cy="56" r="46" style="stroke-dashoffset:${off}"/></svg><div class="rc"><strong>${sc.score==null?'—':sc.score}</strong><small>${sc.score==null?(sc.future?'not yet':'no score'):'of 100'}</small></div></div><div><div class="tiny">${sel===T?'TODAY’S SCORE':dl(sel).toUpperCase()+' SCORE'}</div><div class="sm1">${insight(ts,done)}</div><div class="sbl">${sc.P.map(p=>p.det).join('<br>')}</div></div></button>
<section class="box glass" style="padding:16px;margin-top:12px"><div class="ttl2"><span>Wellbeing</span><span>${c?'Last check-in '+ago(c.at):'No check-in yet'}</span></div><div style="display:flex;gap:14px;align-items:center">${orbHtml(72,c&&c.mood)}<div style="flex:1">${ciPills(c)}</div></div><button class="btn pri full" style="width:100%;margin-top:14px" data-act="wb">Check in now</button></section>`}
function tasks(){
const o=S.tasks.filter(t=>!t.done).sort(cmp),c=S.tasks.filter(t=>t.done).sort((a,b)=>(b.doneAt||'').localeCompare(a.doneAt||''));
return`<div style="height:22px"></div>`+sech('Commitments',`${o.length} open · ${c.length} completed`,`<button class="btn pri" data-act="add">＋ Add task</button>`)+
`<div class="tiny" style="margin:0 4px 8px">OPEN</div><section class="box glass">${o.length?o.map(taskRow).join(''):'<div class="empty">No open tasks. Tap Add task to start.</div>'}</section>
<div class="tiny" style="margin:18px 4px 8px">COMPLETED</div><section class="box glass">${c.length?c.map(taskRow).join(''):'<div class="empty">Completed tasks appear here.</div>'}</section>`}
const EV={created:'Added',done:'Completed',undone:'Reopened',edited:'Edited',deleted:'Deleted'};
function taskHistory(){const e=[...S.events].reverse().slice(0,100);
return`<div style="height:22px"></div>`+`<section class="box glass">${e.length?e.map(x=>`<div class="ev"><b>${x.type==='level'?'Level '+x.level+' unlocked':EV[x.type]+': '+esc(x.title||'')}</b><div style="color:var(--mut);font-size:11px;margin-top:2px">${new Date(x.at).toLocaleString(undefined,{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}</div></div>`).join(''):'<div class="empty">Nothing recorded yet.</div>'}</section>`}
const reportsOld=()=>`<div style="height:22px"></div>`+sech('Reports & insights','Built from your real records, never invented.')+`<section class="box glass"><div class="empty">No reports yet. Charts and patterns arrive after mood and time logs exist.</div></section>`;
function render(){genNotes();pomoStep();$('#v').innerHTML={home,tasks,time,wellbeing,history,reports}[tab]();first=false;
$('#nv').innerHTML=[['home','Home','⌂'],['tasks','Tasks','✓'],['time','Time','◔'],['wellbeing','Wellbeing','♡'],['reports','Reports','▥']].map(([k,l,i])=>`<button class="${tab===k?'on':''}" data-act="tab" data-v="${k}"><span>${i}</span>${l}</button>`).join('');
$('#bn').textContent=S.settings.name||'mindspace';$('#sn').textContent=streaks().cur;const un=S.notifications.filter(n=>!n.read).length;$('#bd').textContent=un>9?'9+':un;$('#bd').style.display=un?'':'none'}
function open(h){$('#sh').innerHTML=`<div class="sheet">${h}</div>`;$('#sh').classList.add('open')}
function close(){$('#sh').classList.remove('open');sheet=null;delArm=false}
function taskSheet(id){const t=id&&S.tasks.find(x=>x.id===id),v=t||{title:'',priority:'medium',date:sel};sheet={id,priority:v.priority};
open(`<h2>${t?'Edit task':'New task'}</h2><label for="f-t">TITLE</label><input type="text" id="f-t" maxlength="120" value="${esc(v.title)}" placeholder="What needs doing?"><label>PRIORITY</label><div class="seg" id="pr">${['high','medium','low'].map(p=>`<button data-act="prio" data-v="${p}" class="${p===v.priority?'on':''}">${PL[p]}</button>`).join('')}</div><label for="f-d">DATE</label><input type="date" id="f-d" value="${v.date}"><div class="acts">${t?`<button class="btn red full" data-act="del">Delete</button>`:''}<button class="btn pri full" data-act="save">Save task</button></div>`);
if(!t)setTimeout(()=>$('#f-t').focus(),60)}
function profileSheet(){sheet={p:1};const s=S.settings,CH='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>';
open(`<h2>Profile</h2><div class="mrow" style="border:0"></div><button class="mrow" data-act="hist"><span>History<small>Time, tasks and mood records</small></span>${CH}</button><button class="mrow" data-act="notes"><span>Notifications<small>Reminders and notices</small></span>${CH}</button><button class="mrow" data-act="export"><span>Export data<small>Choose types, dates and format</small></span>${CH}</button><button class="mrow" data-act="imp"><span>Import backup</span>${CH}</button>
<label for="p-n">DISPLAY NAME</label><input type="text" id="p-n" maxlength="30" value="${esc(s.name)}" placeholder="Optional"><label for="p-g">DAILY TASK GOAL</label><input type="number" id="p-g" min="1" max="50" value="${s.goal}"><label>SOUND EFFECTS</label><div class="seg"><button data-act="snd" data-v="1" class="${s.sound?'on':''}">On</button><button data-act="snd" data-v="0" class="${!s.sound?'on':''}">Off</button></div><div class="two" style="margin-top:16px"><button class="btn full" data-act="ldemo">Load sample data</button><button class="btn full" data-act="rmdemo">Remove sample data</button></div><p style="color:var(--mut);font-size:12px;line-height:1.6;margin:16px 0 0">Your data is stored only in this browser on this phone and does not sync anywhere. Use Export data to save a copy.</p><div class="acts"><button class="btn red full" data-act="delall">Delete local data</button><button class="btn pri full" data-act="psave">Done</button></div>`)}
function fly(id,txt){if(reduce())return;const b=document.querySelector(`.tick[data-id="${id}"]`);if(!b)return;const r=b.getBoundingClientRect(),e=document.createElement('div');e.className='fly';e.textContent=txt;e.style.left=r.left+'px';e.style.top=r.top+'px';document.body.appendChild(e);setTimeout(()=>e.remove(),950)}
function toggle(id){const t=S.tasks.find(x=>x.id===id);if(!t)return;let rew=0;
if(!t.done){t.done=true;t.doneAt=new Date().toISOString();log('done',t);snd('done');
if(!t.rewarded){const b=level(S.coins);S.coins+=10;t.rewarded=true;rew=1;if(level(S.coins)>b){log('level',null,{level:level(S.coins)});note('lv-'+level(S.coins),'progress','Level '+level(S.coins)+' unlocked. Keep it up.');setTimeout(()=>{snd('lvl');toast('Level '+level(S.coins)+' unlocked')},350)}}}
else{t.done=false;t.doneAt=null;log('undone',t);if(t.rewarded){S.coins=Math.max(0,S.coins-10);t.rewarded=false}}
save();render();if(rew)fly(id,'+10')}
